recipes.code:
{
  "inputs": [
    {
      "id": "frase-api-key",
      "type": "promptString",
      "description": "Your Frase API key from Settings > API (https://next.frase.io/settings/api)",
      "password": true
    }
  ],
  "servers": {
    "server": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@frase/mcp-server@0.6.3"
      ],
      "env": {
        "FRASE_API_KEY": "${input:frase-api-key}",
        "FRASE_API_URL": "<frase-api-url>"
      }
    }
  }
}
